import{_ as l,C as t,o,c as d,E as a,a2 as n}from"./chunks/framework.IIAdu7fg.js";const _=JSON.parse('{"title":"排序没变，福利比较却反转：一个保留共同最优解的小实验","description":"","frontmatter":{"title":"排序没变，福利比较却反转：一个保留共同最优解的小实验","date":"2026-10-21","column":"digital-employee","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"个人排序不变时，福利比较能否反转？","summary":"一个三人三书的合成实验显示，排序相同不足以确定所有分配的福利次序；它没有复现真实市场，也没有推翻来源报告的偏好表示分解。","sources":"Project Swap; Strategic Tradeoffs v1; 2026-10-21 internal experiment","pageClass":"runtime-v6-article","item_id":"SIG-20261021-005","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-21-sig-20261021-005-2026-10-21-preference-spacing.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-10-21-preference-spacing.md","filePath":"zh/digital-employee/2026-10-21-preference-spacing.md","lastUpdated":1792585003000}'),c={name:"zh/digital-employee/2026-10-21-preference-spacing.md"};function p(s,e,h,g,f,b){const r=t("ArticleCover"),i=t("ArticleTableScroll");return o(),d("div",null,[a(r,{image:"/assets/covers/daily-2026-10-21-sig-20261021-005-2026-10-21-preference-spacing.png",kicker:"研究成果",title:"排序没变，福利比较却反转：一个保留共同最优解的小实验",summary:"一个三人三书的合成实验显示，排序相同不足以确定所有分配的福利次序；它没有复现真实市场，也没有推翻来源报告的偏好表示分解。",version:"2026-10-21",languageHref:"/en/digital-employee/2026-10-21-preference-spacing",languageLabel:"English"}),a(i,{language:"zh"}),e[0]||(e[0]=n('<h1 id="排序没变-福利比较却反转-一个保留共同最优解的小实验" tabindex="-1">排序没变，福利比较却反转：一个保留共同最优解的小实验 <a class="header-anchor" href="#排序没变-福利比较却反转-一个保留共同最优解的小实验" aria-label="Permalink to &quot;排序没变，福利比较却反转：一个保留共同最优解的小实验&quot;">​</a></h1><p>同一群人对每本书的先后偏好完全不变，两个分配方案谁“更好”，却可以因评分间距不同而交换位置。对评估代理是否忠实代表人的研究者，这意味着不能把排序一致率当成唯一的福利标尺。本文给出一个可逐项核算的反例，并保留它没有改变最优解的边界。</p><h2 id="来源报告的-85-在衡量什么" tabindex="-1">来源报告的 85% 在衡量什么 <a class="header-anchor" href="#来源报告的-85-在衡量什么" aria-label="Permalink to &quot;来源报告的 85% 在衡量什么&quot;">​</a></h2><p>Anthropic（人工智能研究公司）的 Project Swap（代理图书交换研究）报告，模型与人的成对偏好一致率为 61%。用人的排序评价时，人类排序下的最优分配得分为 0.89，按模型排序优化的分配为 0.60，分散交换结果为 0.55。作者据此将相对于最优分配的差距，主要归于偏好表示，而非给定表示后的分配执行。<a href="https://www.anthropic.com/research/project-swap" target="_blank" rel="noreferrer">研究报告，方法及图 3—5</a></p><p>按这些已四舍五入的来源数字，偏好表示对应的差距份额为 <code>(0.89−0.60)/(0.89−0.55)</code>，约 85%。这是对作者所报数字的算术核对，不是一次独立估计。它回答的是特定参与者、评分和插补规则下的分解问题。</p><p>排序只告诉我们一本书优于另一本书。把名次转成可以相加的效用，还需要决定“第一比第二好多少”。来源明确采用线性名次效用，并插补未排序书籍；也报告了对若干插补选择的稳健性。下面改变的是评分间距，不能把它当成对该插补稳健性声明的反证。<a href="https://www.anthropic.com/research/project-swap" target="_blank" rel="noreferrer">方法注释 12—18</a></p><h2 id="固定排序下的福利反转" tabindex="-1">固定排序下的福利反转 <a class="header-anchor" href="#固定排序下的福利反转" aria-label="Permalink to &quot;固定排序下的福利反转&quot;">​</a></h2><p>本研究中心在 2026-10-21 完成的内部实验，枚举三人、三本书的 216 个完整排序组合，每个组合考察六种一人一本的分配。它没有代理、谈判或真实参与者。对从零开始的名次 <code>r</code>，分别采用线性分数 <code>(2−r)/2</code> 和其平方；对应前三名分数是 <code>1、0.5、0</code> 与 <code>1、0.25、0</code>。两种规则保持每个人的全部偏好次序和同一可行分配集合。记录中的 18 项成对次序检查全部通过。</p><p>找到的反例中，三人的排序如下。“甲乙丙”表示三本书，而不是三个得分等级。</p><table tabindex="0"><thead><tr><th>人</th><th>从最喜欢到最不喜欢</th></tr></thead><tbody><tr><td>第一人</td><td>甲、乙、丙</td></tr><tr><td>第二人</td><td>甲、丙、乙</td></tr><tr><td>第三人</td><td>乙、甲、丙</td></tr></tbody></table><p>下表均为内部合成实验的平均分；分配顺序对应第一、第二、第三人。它描述这一个排序组合，不是来源市场的结果。</p><table tabindex="0"><thead><tr><th>分配</th><th>三人所得书籍</th><th style="text-align:right;">线性平均分</th><th style="text-align:right;">平方平均分</th></tr></thead><tbody><tr><td>方案一</td><td>甲、乙、丙</td><td style="text-align:right;">1/3</td><td style="text-align:right;">1/3</td></tr><tr><td>方案二</td><td>乙、丙、甲</td><td style="text-align:right;">1/2</td><td style="text-align:right;">1/4</td></tr><tr><td>两种规则共同的最优分配</td><td>甲、丙、乙</td><td style="text-align:right;">5/6</td><td style="text-align:right;">3/4</td></tr></tbody></table><p>在线性规则下，方案二胜过方案一；在平方规则下，方案一胜过方案二。机制很具体：方案一让一人取得第一名、两人取得末名；方案二让三人都取得第二名。压低第二名的效用会改变两种分配的总分关系，却没有改变任何人的先后排序。该反例是内部实验依据，不是第三方对原研究的复现。</p><h2 id="最优分配没有分离" tabindex="-1">最优分配没有分离 <a class="header-anchor" href="#最优分配没有分离" aria-label="Permalink to &quot;最优分配没有分离&quot;">​</a></h2><p>反例展示的是两个可行结果的次序反转，不是最优结果的次序反转。对上面这个排序组合，两种评分的最优分配相同，都是“甲、丙、乙”。</p><p>更重要的负结果是：全部 216 个排序组合中，没有发现两种规则的最优分配集合完全不相交。实验保留每个精确并列最优分配，而不是随意选一个代表。这个结果不等于两种规则在所有组合里都有完全相同的最优集合，也不支持推广到更大市场。</p><p>因此，“相同排序不决定所有福利比较”有这个小实验支持；“换一种评分就会改变最优分配”不能由本实验推出。将两句话混写，会把一个可核验的反例升级成没有获得的结果。</p><h2 id="偏好表示与谈判是不同任务" tabindex="-1">偏好表示与谈判是不同任务 <a class="header-anchor" href="#偏好表示与谈判是不同任务" aria-label="Permalink to &quot;偏好表示与谈判是不同任务&quot;">​</a></h2><p>在换书研究中，代理先要推断委托人的偏好，再在这份表示上参与交换。作为方法比较，Strategic Tradeoffs（策略权衡研究）的公开第一版给匹配代理直接提供私人估值，研究三人、九回合筹码游戏中的谈判表现。该文报告部分总体剩余结果与人类相近，但交易行为不同；它不承担同一种偏好推断任务。<a href="https://arxiv.org/html/2509.09071v1" target="_blank" rel="noreferrer">公开第一版，第 3—8 节</a></p><p>我们的解释是，评估应分开报告四个问题：偏好怎样取得，排序怎样转成效用，给定这份表示后的协商表现，以及最终是否真实交付。它们各有输入与失败条件。一个按给定分数正确执行的优化器，仍可能服务于失真的偏好表示；相反，偏好获取准确也不保证交换兑现。本文没有执行谈判或交付实验，因此这两项是评价分账建议，而不是本次测得的改进。</p><p>两篇研究不能直接拼成模型能力排名。比较文使用明确估值、单次分组和受限游戏规则，换书研究则包含偏好获取与部分排序处理。本文所读的是 2025 年公开第一版；2026 年会议页面访问失败，不能声称已核对两版文本相同。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>本文的“来源报告”是作者在其数据和方法下给出的结果，我们没有重新运行其市场；“内部实验”是本研究中心自己的合成枚举，不具有独立第三方验证的地位；“研究解释”是从这两类材料形成的方法判断。</p><ul><li><a href="https://www.anthropic.com/research/project-swap" target="_blank" rel="noreferrer">代理图书交换研究</a>：Anthropic，研究报告，本轮读取版本捕获于 2026-10-21；直接支持来源的评分、偏好一致率及差距分解陈述，不支持我们独立测得这些数字。</li><li><a href="https://www-cdn.anthropic.com/files/4zrzovbb/website/7dcd7d8de6e132048f391f5201439c5e11b9fb2c.pdf" target="_blank" rel="noreferrer">图书交换研究附录</a>：同一作者体系的公开附录，方法与限制材料；不是第二份独立验证。</li><li><a href="https://arxiv.org/html/2509.09071v1" target="_blank" rel="noreferrer">策略权衡研究第一版</a>：研究论文，2025 年公开版本；作为明确估值谈判任务的比较材料，不是对换书结果的复现或背书。</li><li>本研究中心 2026-10-21 内部实验：三人三书、216 个排序组合、每组六种分配；记录保留了全部组合、评分规则、反例与最优集合负结果。没有取得原始参与者数据或可执行市场代码。</li></ul><p>图书交换研究还受员工便利样本、低风险且非激励式排序、末期调查流失、固定市场规则和守规代理等限制。其 200 次重复运行复用人、书和输入，不应被当成 200 份独立参与者样本。<a href="https://www-cdn.anthropic.com/files/4zrzovbb/website/7dcd7d8de6e132048f391f5201439c5e11b9fb2c.pdf" target="_blank" rel="noreferrer">附录及限制说明</a></p><h2 id="需要真实参与者数据回答的问题" tabindex="-1">需要真实参与者数据回答的问题 <a class="header-anchor" href="#需要真实参与者数据回答的问题" aria-label="Permalink to &quot;需要真实参与者数据回答的问题&quot;">​</a></h2><p>要判断来源中市场方案的排名是否对效用间距敏感，需要原始参与者数据，并让参与者提供或约束间距，再重新评价同一分配。本次合成枚举不能替代这一步，也不能重估来源的 85%。</p><p>对代理评估者，当前可执行的动作是先公开评分假设，再把偏好获取、条件执行和交付结果分开。尚未解决的问题是：在真实参与者上，偏好获取准确率能否在控制交付差异后预测满意度？这需要新的证据，本文没有答案。</p>',28))])}const u=l(c,[["render",p]]);export{_ as __pageData,u as default};
